import requests, os
papers = {
    "2303.13408_paraphrasing_evades_detectors.pdf": "https://arxiv.org/pdf/2303.13408",
    "2405.07940_RAID_benchmark.pdf": "https://arxiv.org/pdf/2405.07940",
    "2303.11156_can_AI_text_reliably_detected.pdf": "https://arxiv.org/pdf/2303.11156",
}
for fname, url in papers.items():
    fpath = f"papers/{fname}"
    try:
        r = requests.get(url, timeout=60, headers={"User-Agent": "Mozilla/5.0"})
        if r.status_code == 200 and len(r.content) > 10000:
            with open(fpath, 'wb') as f:
                f.write(r.content)
            print(f"OK   {fname} ({len(r.content)} bytes)")
        else:
            print(f"FAIL {fname} status={r.status_code}")
    except Exception as e:
        print(f"ERR  {fname}: {e}")
PYEOF

