# Check sizes of MAGE and RAID files before downloading
import requests

def hf_file_size(repo_id, filename, repo_type="dataset"):
    url = f"https://huggingface.co/datasets/{repo_id}/resolve/main/{filename}"
    r = requests.head(url, allow_redirects=True, timeout=15)
    size = r.headers.get("Content-Length", "unknown")
    return size

print("MAGE file sizes:")
for f in ["train.csv", "valid.csv", "test.csv", "test_ood_set_gpt.csv"]:
    size = hf_file_size("yaful/MAGE", f)
    if size != "unknown":
        print(f"  {f}: {int(size)/1024/1024:.1f} MB")
    else:
        print(f"  {f}: size unknown")

print("\nRAID file sizes:")
for f in ["test.csv"]:
    size = hf_file_size("liamdugan/raid", f)
    if size != "unknown":
        print(f"  {f}: {int(size)/1024/1024:.1f} MB")
    else:
        print(f"  {f}: size unknown")
EOF
